{"function":"() => {
// contrast calc
const parse=c=>c.match(/[\d.]+/g).map(Number);
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const cr=(a,b)=>{const l1=lum(a),l2=lum(b);return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)};
const bgOf=e=>{while(e){const c=getComputedStyle(e).backgroundColor; const p=parse(c); if(p.length<4||p[3]>0) return p.slice(0,3); e=e.parentElement;} return [255,255,255]};
const sample=(e)=>{const cs=getComputedStyle(e); return {text:e.textContent.trim().slice(0,40), color:cs.color, bg:bgOf(e).join(','), fs:cs.fontSize, fw:cs.fontWeight, ratio:cr(parse(cs.color).slice(0,3),bgOf(e))}};
const els=[];
document.querySelectorAll('pnip-status-solicitacao-utils .text-center').forEach(e=>els.push(sample(e)));
const q=(s)=>document.querySelectorAll(s);
['th','td','.br-tag span','.br-tag','main a'].forEach(s=>{const e=q(s)[1]||q(s)[0]; if(e) els.push({s,...sample(e)})});
// ultima atualizacao
const ua=[...document.querySelectorAll('main *')].find(e=>e.childElementCount<3 && e.textContent.trim().startsWith('Última atualização'));
if(ua) els.push({s:'ultima',...sample(ua), cls:ua.className});
return els;}"}

