const cr=(a,b)=>{const l1=lum(a),l2=lum(b);return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)};
const badges=[...document.querySelectorAll('pnip-status-solicitacao-utils .text-center')].map(e=>[e.textContent.trim(), e.parentElement.className, getComputedStyle(e.parentElement).backgroundColor]);
const th=document.querySelectorAll('th')[2]; const thc=getComputedStyle(th);
const tr=getComputedStyle(th.parentElement).backgroundColor, thead=getComputedStyle(document.querySelector('thead')).backgroundColor;
